E=np.array(cm['extrinsic_cv']);Ei=np.linalg.inv(np.vstack([E,[0,0,0,1]]));K=np.array(cm['intrinsic_cv']);
# central white image object region x=350:580 y=0:320, only pixels near object
for box in [(350,0,580,320),(300,0,600,320),(0,0,848,480)]:
 x0,y0,x1,y1=box; ys,xs=np.mgrid[y0:y1:4,x0:x1:4];zz=d[ys,xs];valid=zz>0; xx=(xs-K[0,2])*zz/K[0,0]; yy=(ys-K[1,2])*zz/K[1,1]; pc=np.stack([xx,yy,zz,np.ones_like(zz)],-1); pw=pc@Ei.T; w=pw[...,:3][valid]; colors=im[ys,xs][valid];
 mask=(colors.mean(axis=1)>150)&(w[:,2]>.77)&(w[:,2]<.90)
